def get_total_number_of_sequences(m, n, memo=None):
    if memo is None:
        memo = {}

    if (m, n) in memo:
        return memo[(m, n)]

    if n == 0:
        return 1

    if m < n:
        return 0

    count = 0
    for i in range(n, m + 1):
        count += get_total_number_of_sequences(i // 2, n - 1, memo)

    memo[(m, n)] = count
    return count
"""
  }
}
